        <div style={{marginTop:48,fontFamily:"'Share Tech Mono',monospace",fontSize:10,color:"#1a2a1a",letterSpacing:2,textTransform:"uppercase",animation:"fadeInUp .5s ease 1s both"}}>SYS // UNITY · REACT · VR · MOBILE · MEDELLÍN</div>
