/* ─── SCROLL TO TOP ──────────────────────────────────────── */
function ScrollToTop() {
  const [show, setShow] = useState(false);
  useEffect(() => {
    const el = document.getElementById('main-scroll');
    const onScroll = () => setShow((el?.scrollTop || 0) > 300);
    el?.addEventListener('scroll', onScroll);
    return () => el?.removeEventListener('scroll', onScroll);
  }, []);
  const scrollUp = () => document.getElementById('main-scroll')?.scrollTo({top:0,behavior:'smooth'});
  if (!show) return null;
  return (
    <button className="scroll-top-btn" onClick={scrollUp} title="Volver arriba"
      style={{opacity: show ? 1 : 0, transform: show ? 'translateY(0)' : 'translateY(20px)', transition:'opacity .3s,transform .3s'}}>
      ↑
    </button>
  );
}

