/* ══════════ ANIMATED AVATAR ══════════ */
const AVATAR_B64 = "";
function Avatar({ size=120 }) {
  const [glitch, setGlitch] = useState(false);
  const [hov, setHov] = useState(false);
  useEffect(() => {
    const gi = setInterval(() => { setGlitch(true); setTimeout(()=>setGlitch(false), 180); }, 3800);
    return () => clearInterval(gi);
  }, []);
  const r = size / 2;
  const border = size * 0.055;
  return (
    <div onMouseEnter={()=>setHov(true)} onMouseLeave={()=>setHov(false)}
      style={{ position:"relative", width:size, height:size, flexShrink:0, cursor:"none" }}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ overflow:"visible" }}>
        <defs>
          <clipPath id="avatarClip"><circle cx={r} cy={r} r={r - border - 3}/></clipPath>
          <radialGradient id="glowGrad" cx="50%" cy="50%">
            <stop offset="0%" stopColor="#00f5c4" stopOpacity={hov?"0.25":"0.1"}/>
            <stop offset="100%" stopColor="#00f5c4" stopOpacity="0"/>
          </radialGradient>
          <linearGradient id="ringGrad" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor={glitch?"#ff3d6b":"#00f5c4"}/>
            <stop offset="40%" stopColor={glitch?"#5b9cf6":"#5b9cf6"}/>
            <stop offset="100%" stopColor={glitch?"#ffd060":"#ff3d6b"}/>
          </linearGradient>
          <filter id="glitchFilter">
            <feColorMatrix type="saturate" values="1.4"/>
          </filter>
        </defs>

        {/* Outer glow pulse */}
        <circle cx={r} cy={r} r={r + 4} fill="url(#glowGrad)"
          style={{ transition:"all .3s" }}/>

        {/* Spinning RGB border */}
        <circle cx={r} cy={r} r={r - border/2} fill="none"
          stroke="url(#ringGrad)" strokeWidth={border}
          strokeDasharray={hov ? `${r*1.5} ${r*0.3}` : `${r*4} ${r*0.8}`}
          style={{ animation:`rotateSlow ${hov?"2s":"4s"} linear infinite`,
                    transition:"stroke-dasharray .4s, filter .2s",
                    filter: glitch?"drop-shadow(0 0 6px #ff3d6b)":"drop-shadow(0 0 8px #00f5c4)" }}/>

        {/* Second counter-rotating ring */}
        <circle cx={r} cy={r} r={r - border/2 - 3} fill="none"
          stroke="rgba(91,156,246,0.25)" strokeWidth="1.5"
          strokeDasharray={`${r*1} ${r*0.5}`}
          style={{ animation:"rotateSlow 8s linear infinite reverse" }}/>

        {/* Photo */}
        <image href={`data:image/png;base64,${AVATAR_B64}`}
          x={border+3} y={border+3}
          width={size - (border+3)*2} height={size - (border+3)*2}
          clipPath="url(#avatarClip)"
          style={{ transform: glitch?`translate(${glitch?2:0}px,0) scale(1.02)`:"scale(1)",
                    transition:"transform .1s",
                    filter: glitch?"hue-rotate(30deg) saturate(1.5)":"none" }}/>

        {/* Glitch color split overlay */}
        {glitch && <>
          <image href={`data:image/png;base64,${AVATAR_B64}`}
            x={border+3+3} y={border+3}
            width={size-(border+3)*2} height={size-(border+3)*2}
            clipPath="url(#avatarClip)"
            style={{ mixBlendMode:"screen", opacity:0.35,
              filter:"url(#glitchFilter) hue-rotate(180deg)" }}/>
        </>}

        {/* Scanline overlay */}
        <circle cx={r} cy={r} r={r - border - 3} fill="none"
          clipPath="url(#avatarClip)"
          style={{ backgroundImage:"repeating-linear-gradient(0deg,transparent,transparent 3px,rgba(0,0,0,0.06) 3px,rgba(0,0,0,0.06) 4px)" }}/>

        {/* HUD corners */}
        {[[4,4,"right","bottom"],[size-4,4,"left","bottom"],[4,size-4,"right","top"],[size-4,size-4,"left","top"]].map(([x,y,h,v],i)=>(
          <g key={i}>
            <line x1={x} y1={y} x2={h==="right"?x+10:x-10} y2={y} stroke="#00f5c4" strokeWidth="1.5" opacity="0.6"/>
            <line x1={x} y1={y} x2={x} y2={v==="bottom"?y+10:y-10} stroke="#00f5c4" strokeWidth="1.5" opacity="0.6"/>
          </g>
        ))}

        {/* Online indicator */}
        <circle cx={r + r*0.6} cy={r - r*0.6} r={size*0.07} fill="#06090f" stroke="#00f5c4" strokeWidth="1.5"/>
        <circle cx={r + r*0.6} cy={r - r*0.6} r={size*0.042} fill="#00f5c4"
          style={{ animation:"pulse 1.5s ease-in-out infinite" }}/>
      </svg>
    </div>
  );
}

/* ══════════ CURSOR PARTICLE TRAIL ══════════ */
function CursorTrail() {
  const trailRef = useRef([]);
  const frameRef = useRef(null);
  const COLORS = ["#00f5c4","#5b9cf6","#ff3d6b","#ffd060","#a78bfa"];

  useEffect(() => {
    const onMove = (e) => {
      const particle = {
        x: e.clientX, y: e.clientY,
        life: 1.0,
        color: COLORS[Math.floor(Math.random() * COLORS.length)],
        size: Math.random() * 4 + 2,
        vx: (Math.random() - 0.5) * 1.5,
        vy: (Math.random() - 0.5) * 1.5 - 0.5,
      };
      trailRef.current.push(particle);
      if (trailRef.current.length > 28) trailRef.current.shift();
    };
    window.addEventListener("mousemove", onMove);
    return () => window.removeEventListener("mousemove", onMove);
  }, []);

  useEffect(() => {
    const canvas = document.getElementById("cursor-trail-canvas");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    let W = canvas.width  = window.innerWidth;
    let H = canvas.height = window.innerHeight;
    const resize = () => { W = canvas.width = window.innerWidth; H = canvas.height = window.innerHeight; };
    window.addEventListener("resize", resize);

    const tick = () => {
      ctx.clearRect(0, 0, W, H);
      trailRef.current = trailRef.current.filter(p => p.life > 0.02);
      trailRef.current.forEach(p => {
        p.life -= 0.045;
        p.x += p.vx; p.y += p.vy;
        p.vx *= 0.95; p.vy *= 0.95;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
        ctx.fillStyle = p.color;
        ctx.globalAlpha = p.life * 0.7;
        ctx.fill();
        ctx.globalAlpha = 1;
      });
      frameRef.current = requestAnimationFrame(tick);
    };
    frameRef.current = requestAnimationFrame(tick);
    return () => { cancelAnimationFrame(frameRef.current); window.removeEventListener("resize", resize); };
  }, []);

  return <canvas id="cursor-trail-canvas" style={{ position:"fixed", inset:0, zIndex:99997, pointerEvents:"none" }}/>;
}

/* ══════════ KONAMI EASTER EGG ══════════ */
function KonamiEgg() {
  const [active, setActive] = useState(false);
  const [particles, setParticles] = useState([]);
  const seqRef = useRef([]);
  const KONAMI = ["ArrowUp","ArrowUp","ArrowDown","ArrowDown","ArrowLeft","ArrowRight","ArrowLeft","ArrowRight","b","a"];

  useEffect(() => {
    const onKey = (e) => {
      seqRef.current = [...seqRef.current, e.key].slice(-10);
      if (seqRef.current.join(",") === KONAMI.join(",")) {
        setActive(true); if(window.__jdgUnlock) window.__jdgUnlock("hacker");
        // Spawn explosion particles
        const pts = Array.from({length: 80}, (_, i) => ({
          id: i,
          x: window.innerWidth / 2,
          y: window.innerHeight / 2,
          angle: (i / 80) * Math.PI * 2,
          speed: Math.random() * 8 + 3,
          color: ["#00f5c4","#ff3d6b","#5b9cf6","#ffd060","#a78bfa","#fff"][i % 6],
          size: Math.random() * 10 + 4,
          life: 1,
          emoji: ["🎮","⚡","🌌","🔥","💜","⭐","🚀","🎯"][i % 8],
        }));
        setParticles(pts);
        setTimeout(() => { setActive(false); setParticles([]); }, 5000);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  if (!active) return null;

  return (
    <div style={{ position:"fixed", inset:0, zIndex:99996, pointerEvents:"none" }}>
      {/* Dark overlay */}
      <div style={{ position:"absolute", inset:0, background:"rgba(0,0,0,0.85)", animation:"fadeIn .3s ease" }}/>

      {/* Center message */}
      <div style={{ position:"absolute", top:"50%", left:"50%", transform:"translate(-50%,-50%)", textAlign:"center", zIndex:2 }}>
        <div style={{ fontFamily:"'Orbitron',monospace", fontSize:"clamp(28px,5vw,56px)", fontWeight:900,
          background:"linear-gradient(90deg,#00f5c4,#ff3d6b,#5b9cf6,#ffd060)", WebkitBackgroundClip:"text", WebkitTextFillColor:"transparent",
          animation:"shimmer 1s linear infinite", backgroundSize:"200%", marginBottom:16, lineHeight:1.2 }}>
          ↑↑↓↓←→←→BA
        </div>
        <div style={{ fontFamily:"'Orbitron',monospace", fontSize:18, fontWeight:700, color:"#00f5c4", letterSpacing:3, marginBottom:8 }}>
          CHEAT CODE ACTIVADO
        </div>
        <div style={{ fontFamily:"'Share Tech Mono',monospace", fontSize:13, color:"#6a7a90", letterSpacing:2 }}>
          +30 VIDAS · GOD MODE · INFINITE AMMO
        </div>
        <div style={{ marginTop:20, fontSize:32 }}>🎮 ⚡ 🌌</div>
      </div>

      {/* Particle explosion */}
      {particles.map(p => (
        <div key={p.id} style={{
          position:"absolute",
          left: p.x, top: p.y,
          fontSize: p.size * 2,
          animation: `particleFade 2.5s ease-out ${p.id * 0.02}s both`,
          transform: `translate(-50%,-50%) rotate(${p.angle}rad)`,
          transformOrigin: "center",
        }}>
          <span style={{ display:"inline-block",
            transform:`translate(${Math.cos(p.angle) * p.speed * 30}px,${Math.sin(p.angle) * p.speed * 30}px)`,
            transition:"transform 2s ease-out" }}>
            {p.emoji}
          </span>
        </div>
      ))}
    </div>
  );
}


/* ══════════ FAVICON ══════════ */
