/* ══════════ TYPING TEXT EFFECT ══════════ */
function TypingText({ texts, speed=55, pause=2200 }) {
  const [displayed, setDisplayed] = useState("");
  const [tIdx, setTIdx] = useState(0);
  const [cIdx, setCIdx] = useState(0);
  const [deleting, setDeleting] = useState(false);
  const [showCursor, setShowCursor] = useState(true);

  useEffect(() => {
    const current = texts[tIdx];
    let timeout;
    if (!deleting && cIdx <= current.length) {
      timeout = setTimeout(() => { setDisplayed(current.slice(0, cIdx)); setCIdx(c=>c+1); },
        cIdx === current.length ? pause : speed);
    } else if (!deleting && cIdx > current.length) {
      timeout = setTimeout(() => setDeleting(true), pause);
    } else if (deleting && cIdx >= 0) {
      timeout = setTimeout(() => { setDisplayed(current.slice(0, cIdx)); setCIdx(c=>c-1); }, speed/2);
    } else {
      setDeleting(false); setTIdx(t=>(t+1)%texts.length); setCIdx(0);
    }
    return () => clearTimeout(timeout);
  }, [cIdx, deleting, tIdx, texts, speed, pause]);

  return (
    <span>
      <span>{displayed}</span>
      <span className="typing-cursor"/>
    </span>
  );
}

/* ══════════ MATRIX RAIN ══════════ */
function MatrixRain() {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    let W = canvas.width = window.innerWidth;
    let H = canvas.height = window.innerHeight;
    const resize = () => { W = canvas.width = window.innerWidth; H = canvas.height = window.innerHeight; };
    window.addEventListener("resize", resize);
    const COLS = Math.floor(W / 16);
    const drops = Array(COLS).fill(0).map(() => Math.random() * -50);
    const CHARS = "アイウエオカキクケコサシスセソタチツテトナニヌネノ0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ</>{}[]";
    let raf;
    const draw = () => {
      ctx.fillStyle = "rgba(0,0,0,0.04)";
      ctx.fillRect(0,0,W,H);
      ctx.font = "14px 'Share Tech Mono',monospace";
      drops.forEach((y,i) => {
        const char = CHARS[Math.floor(Math.random()*CHARS.length)];
        const bright = Math.random() > 0.95;
        ctx.fillStyle = bright ? "#afffcf" : "#00ff41";
        ctx.fillText(char, i*16, y*16);
        if (y*16 > H && Math.random() > 0.975) drops[i] = 0;
        else drops[i]++;
      });
      raf = requestAnimationFrame(draw);
    };
    draw();
    return () => { cancelAnimationFrame(raf); window.removeEventListener("resize", resize); };
  }, []);
  return <canvas ref={canvasRef} id="matrix-canvas"/>;
}

